const assets=['BTC','ETH','BNB','SOL','XRP'];let selected='BTC',period='1h';const fallback={BTC:[78742,1.42,24100000000],ETH:[2476,.88,13200000000],BNB:[736,-1.23,1860000000],SOL:[162.4,2.61,3580000000],XRP:[1.38,-1.97,2250000000]};
const fmt=n=>n>=1e9?'$'+(n/1e9).toFixed(2)+'B':n>=1e6?'$'+(n/1e6).toFixed(1)+'M':'$'+Number(n).toLocaleString(undefined,{maximumFractionDigits:2});
function renderStrip(data=fallback){document.querySelector('#marketStrip').innerHTML=assets.map(a=>{const d=data[a]||fallback[a];return `<div class="ticker"><div><b>${a}/USDT</b><small class="${d[1]>=0?'up':'down'}">${d[1]>=0?'+':''}${d[1].toFixed(2)}%</small></div><strong>${fmt(d[0])}</strong></div>`}).join('')}
function renderSymbols(){document.querySelector('#symbols').innerHTML=assets.map(a=>`<button class="symbol ${a===selected?'on':''}" data-symbol="${a}">${a}</button>`).join('');document.querySelectorAll('.symbol').forEach(b=>b.onclick=()=>{selected=b.dataset.symbol;renderSymbols()})}
async function live(){try{const res=await fetch('https://api.binance.com/api/v3/ticker/24hr');const rows=await res.json();const data={};assets.forEach(a=>{const x=rows.find(r=>r.symbol===a+'USDT');if(x)data[a]=[+x.lastPrice,+x.priceChangePercent,+x.quoteVolume]});if(Object.keys(data).length)renderStrip(data)}catch(e){renderStrip()}}
function analyze(){const run=document.querySelector('#run');run.classList.add('loading');run.querySelector('span').textContent='Agent 正在分析…';setTimeout(()=>{const d=fallback[selected];const risk=+document.querySelector('#risk').value;const trend=Math.max(0,Math.min(100,52+d[1]*7));const liquidity=Math.min(100,45+Math.log10(d[2])*5);const vol=Math.min(100,Math.abs(d[1])*14+28);let score=Math.round(trend*.43+liquidity*.34+(100-vol)*.23+(risk-2)*5);score=Math.max(20,Math.min(94,score));let verdict=score>=72?'可关注':score>=52?'等待确认':'暂不交易';document.querySelector('#empty').classList.add('hidden');document.querySelector('#report').classList.remove('hidden');document.querySelector('#score').textContent=score;document.querySelector('#meter').style.width=score+'%';document.querySelector('#verdict').textContent=verdict;document.querySelector('#verdict').className=score>=72?'up':score<52?'down':'';document.querySelector('#change').textContent=(d[1]>=0?'+':'')+d[1].toFixed(2)+'%';document.querySelector('#change').className=d[1]>=0?'up':'down';document.querySelector('#volume').textContent=fmt(d[2]);document.querySelector('#volatility').textContent=vol<45?'低':vol<65?'中':'高';document.querySelector('#freshness').textContent='刚刚更新';document.querySelector('#freshness').className='badge';document.querySelector('#reasons').innerHTML=[`${selected} 在 ${period} 周期的趋势分为 ${Math.round(trend)}/100。`,`24H 成交额 ${fmt(d[2])}，主流交易对流动性条件通过。`,`波动强度为${vol<45?'低':vol<65?'中':'高'}，当前风险偏好已纳入评分。`,score>=72?'具备观察价值，但仍需等待入场触发条件。':score>=52?'方向尚未形成共振，建议等待二次确认。':'风险收益比不足，Agent 建议跳过本次机会。'].map(x=>`<li>${x}</li>`).join('');run.classList.remove('loading');run.querySelector('span').textContent='重新运行分析'},900)}
document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-period]').forEach(x=>x.classList.remove('on'));b.classList.add('on');period=b.dataset.period});document.querySelector('#run').onclick=analyze;setInterval(()=>document.querySelector('#clock').textContent=new Date().toISOString().slice(11,19)+' UTC',1000);renderStrip();renderSymbols();live();
